long long* applyRanges(int n, const int (*updates)[3], int m) {
    long long* diff = calloc(n + 1, sizeof(long long));
    for (int k = 0; k < m; k++) {
        diff[updates[k][0]] += updates[k][2];
        diff[updates[k][1] + 1] -= updates[k][2];
    }
    long long* result = malloc(n * sizeof(long long));
    long long running = 0;
    for (int i = 0; i < n; i++) {
        running += diff[i];
        result[i] = running;
    }
    free(diff);
    return result;
}

