static int maxOverlap(int[][] intervals) {
    int m = intervals.length;
    long[][] events = new long[2 * m][];
    for (int k = 0; k < m; k++) {
        events[2 * k] = new long[] {intervals[k][0], +1};
        events[2 * k + 1] = new long[] {intervals[k][1], -1};
    }
    Arrays.sort(events, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
    int live = 0, best = 0;
    for (long[] e : events) {
        live += (int) e[1];
        best = Math.max(best, live);
    }
    return best;
}

