typedef struct { int at, delta; } Event;

static int byTimeThenDelta(const void* a, const void* b) {
    const Event *x = a, *y = b;
    if (x->at != y->at) return (x->at > y->at) - (x->at < y->at);
    return x->delta - y->delta;
}

int maxOverlap(const int (*intervals)[2], int m) {
    Event* events = malloc(2 * m * sizeof(Event));
    for (int k = 0; k < m; k++) {
        events[2 * k] = (Event){intervals[k][0], +1};
        events[2 * k + 1] = (Event){intervals[k][1], -1};
    }
    qsort(events, 2 * m, sizeof(Event), byTimeThenDelta);
    int live = 0, best = 0;
    for (int k = 0; k < 2 * m; k++) {
        live += events[k].delta;
        if (live > best) best = live;
    }
    free(events);
    return best;
}

