def paint_rects(rows, cols, rects):
    D = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r1, c1, r2, c2, v in rects:
        D[r1][c1] += v
        D[r1][c2 + 1] -= v
        D[r2 + 1][c1] -= v
        D[r2 + 1][c2 + 1] += v
    for r in range(rows):
        for c in range(1, cols):
            D[r][c] += D[r][c - 1]
    for r in range(1, rows):
        for c in range(cols):
            D[r][c] += D[r - 1][c]
    return [row[:cols] for row in D[:rows]]

