static long[][] paintRects(int rows, int cols, int[][] rects) {
    long[][] D = new long[rows + 1][cols + 1];
    for (int[] q : rects) {
        D[q[0]][q[1]] += q[4];
        D[q[0]][q[3] + 1] -= q[4];
        D[q[2] + 1][q[1]] -= q[4];
        D[q[2] + 1][q[3] + 1] += q[4];
    }
    for (int r = 0; r < rows; r++)
        for (int c = 1; c < cols; c++) D[r][c] += D[r][c - 1];
    for (int r = 1; r < rows; r++)
        for (int c = 0; c < cols; c++) D[r][c] += D[r - 1][c];
    long[][] out = new long[rows][];
    for (int r = 0; r < rows; r++) out[r] = Arrays.copyOf(D[r], cols);
    return out;
}

