// Returns a rows x cols grid in one block (cell (r, c) at r * cols + c); the caller frees it.
long long* paintRects(int rows, int cols, const int (*rects)[5], int m) {
    int w = cols + 1;
    long long* D = calloc((size_t)(rows + 1) * w, sizeof(long long));
    for (int k = 0; k < m; k++) {
        int r1 = rects[k][0], c1 = rects[k][1], r2 = rects[k][2], c2 = rects[k][3], v = rects[k][4];
        D[r1 * w + c1] += v;
        D[r1 * w + c2 + 1] -= v;
        D[(r2 + 1) * w + c1] -= v;
        D[(r2 + 1) * w + c2 + 1] += v;
    }
    for (int r = 0; r < rows; r++)
        for (int c = 1; c < cols; c++) D[r * w + c] += D[r * w + c - 1];
    for (int r = 1; r < rows; r++)
        for (int c = 0; c < cols; c++) D[r * w + c] += D[(r - 1) * w + c];
    long long* out = malloc((size_t)rows * cols * sizeof(long long));
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) out[r * cols + c] = D[r * w + c];
    free(D);
    return out;
}
